#define _POSIX_C_SOURCE 200809L
#include "host.h"

#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

/* Input is generated by game.tick's deterministic bot. No pacing or window. */
bool zrg_platform_poll(void) { return true; }
void zrg_platform_present(void) { }

static bool make_one(const char *path) {
    struct stat info;
    if (mkdir(path, 0777) == 0) return true;
    return errno == EEXIST && stat(path, &info) == 0 && S_ISDIR(info.st_mode);
}

bool zrg_platform_make_directory(const char *directory) {
    char *path = strdup(directory);
    if (!path) return false;
    bool ok = true;
    for (char *p = path + 1; *p && ok; ++p) {
        if (*p != '/') continue;
        *p = '\0';
        ok = make_one(path);
        *p = '/';
    }
    if (ok) ok = make_one(path);
    free(path);
    return ok;
}
